export const BUNDLED_PROMPTS: Readonly<Record<string, string>> = {
  "messages/message-email-followup-v1": "# Generación de mensaje: Follow-up por email — {{PRODUCT}}\n\n## Contexto\nSDR de {{PRODUCT}}. Ya le mandaste a este contacto un email con la propuesta y no\nrespondió. Este es un follow-up corto (step {{STEP_NUMBER}} de la secuencia por email).\n\n## Reglas\n- 2-3 oraciones máximo. Un solo CTA: charla de 15 min (o una respuesta corta).\n- Referenciá el email anterior sin repetir la propuesta entera (\"te escribí la semana pasada por...\").\n- Si el step es 6 o más: es el último toque, cerrá dejando la puerta abierta (\"si no es el momento, cero drama\").\n- NO inventes datos, cifras, clientes ni marcas.\n- Tono rioplatense, cercano, sin jerga corporativa, sin presionar.\n\n## Datos del lead\nEmpresa: {{COMPANY_NAME}}\nContacto: {{CONTACT_NAME}}, {{CONTACT_ROLE}}\nVertical: {{VERTICAL}}\nRegión: {{REGION}}\nDato relevante: {{PROFILE_INSIGHT}}\n\n## Formato\nSUBJECT: [subject, puede ser \"Re: ...\" corto]\nBODY: [cuerpo]\n",
  "messages/message-loop-direct-v1": "# Generación de mensaje: Contacto Directo — Loop\n\n## Contexto\nContacto directo con un lead de Loop. Se usa cuando hay warm path o\nscore muy alto.\n\n## Instrucciones\n- Tono: Directo pero cercano.\n- Usá el pitch angle del buyer persona (ver abajo).\n- Mencioná algo específico del negocio.\n- Call to action: charla de 15 min.\n- NO uses \"solución integral\", \"propuesta de valor\", jerga corporativa.\n- El ángulo eco (sin plástico) es transversal — mencionarlo siempre.\n\n## Pitch por buyer persona\n- BP1 (1-3 locales): \"Tu cliente ya viene. Loop te dice cuándo se va a ir y lo trae de vuelta.\"\n- BP1 (4-15 locales): \"Tus clientes van a cualquiera de tus locales pero no sabés cuántas veces. Loop te lo muestra.\"\n- BP1 (16+ / cadena): \"Loop unifica la fidelización de todos tus puntos gastronómicos en un solo dashboard.\"\n- BP2: \"Tu eco-tarjeta digital es parte de tu marca. Sin plástico, sin papel.\"\n- BP3: \"Tu tarjeta de fidelización en el celular del cliente. Consistente con tu marca sustentable.\"\n- BP4: \"Sin cambiar tu operación, tus clientes acumulan desde el primer día.\"\n- BP5: \"El cliente que falta 3 semanas es el que cancela. Loop te avisa antes.\"\n- BP6: \"Una sola tarjeta digital para todos tus locales. Datos unificados, sin plástico.\"\n\n## Adaptación por tamaño\n- 1-3 locales: \"Cada cliente que se va lo notás directo en la caja.\"\n- 4-9 locales: \"Con Loop medís la recurrencia en todos tus puntos.\"\n- 10+ locales/cadena: \"Loop unifica la fidelización de todas tus sucursales.\"\n\n## Canal: {{CHANNEL}}\n- LinkedIn DM: 5 oraciones, informal\n- Email: 6-7 oraciones + subject line\n- WhatsApp: 4 oraciones, directo\n- Instagram DM: 3-4 oraciones, casual\n\n## Datos\nEmpresa: {{COMPANY_NAME}}\nContacto: {{CONTACT_NAME}}, {{CONTACT_ROLE}}\nSub-sector: {{SUBSECTOR}}\nLocales: {{LOCATIONS_COUNT}}\nRegión: {{REGION}}\nScore: {{TOTAL_SCORE}}\nBuyer persona: {{BUYER_PERSONA}}\nRazonamiento score: {{AI_REASONING}}\nWarm connector: {{WARM_CONNECTOR}}\nDato relevante: {{PROFILE_INSIGHT}}\n\n## Formato\nEmail: SUBJECT: [subject]\\nBODY: [cuerpo]\nOtros: Solo el texto.\n",
  "messages/message-loop-nurture-v1": "# Generación de mensaje: Nurture Sequence — Loop\n\n## Contexto\nSos un SDR de Loop ejecutando una secuencia de calentamiento. El objetivo\nes generar familiaridad antes de cualquier pitch.\n\n## Adaptación por buyer persona\nUsá el buyer persona del lead para adaptar el contenido:\n- BP1 Gastronómico (1-3 locales): ángulo retención visible, datos de frecuencia, cada cliente cuenta\n- BP1 Gastronómico (4-15 locales): ángulo visibilidad entre locales, saber a cuál van\n- BP1 Gastronómico (16+ / cadena): ángulo datos unificados, fidelización centralizada\n- BP2 Wellness/Beauty: ángulo imagen de marca, eco-tarjeta, comunidad\n- BP3 Moda Indie: ángulo sustentabilidad, fidelización digital, fans->clientes\n- BP4 Retail Indie: ángulo ROI, simplicidad, competir con cadenas grandes\n- BP5 Gym/Club: ángulo churn, reactivación, gamificación\n- BP6 Cadena no gastronómica: ángulo datos unificados, escalabilidad, reemplazo de tarjeta física\n\n## Steps\n\n### Step 1: Comentario de valor en post del lead\n- Ángulo según sub-sector (retención, fidelización, experiencia cliente)\n- 2-3 oraciones, aportar dato o perspectiva. NO mencionar Loop.\n\n### Step 2: Recurso de valor\n- Dato relevante para su negocio según buyer persona.\n- Ejemplos BP1 (chico): \"El 60% de los clientes de cafeterías no vuelve después de\n  la 3ra visita si no hay incentivo\"\n- Ejemplos BP1 (cadena): \"Las cadenas gastronómicas que unifican su programa de\n  fidelización ven un 25% más de cross-visits entre locales\"\n- Ejemplos BP5: \"El churn en gyms de Argentina supera el 40% post-verano\"\n- 3-4 oraciones + dato. NO mencionar Loop.\n\n### Step 3: Conexión LinkedIn\n- Nota de 300 chars max. Referenciar interacción anterior. NO mencionar Loop.\n\n### Step 4: Mensaje directo post-conexión\n- Ahora SÍ mencionás Loop.\n- Usá el pitch angle del buyer persona correspondiente.\n- Preguntá si tiene sentido una charla de 15 min.\n- Tono: café, no venta. 4-6 oraciones.\n\n## Datos del lead\nEmpresa: {{COMPANY_NAME}}\nContacto: {{CONTACT_NAME}}, {{CONTACT_ROLE}}\nSub-sector: {{SUBSECTOR}}\nLocales: {{LOCATIONS_COUNT}}\nRegión: {{REGION}}\nBuyer persona: {{BUYER_PERSONA}}\nInstagram: {{SOCIAL_PROFILE}}\nDato relevante: {{PROFILE_INSIGHT}}\n\n## Step a generar: {{STEP_NUMBER}}\n## Formato: Solo el texto del mensaje del step indicado.\n",
  "messages/message-loop-warm-intro-v1": "# Generación de mensaje: Warm Intro — Loop\n\n## Contexto\nSos un SDR de Loop pidiendo una warm intro a un contacto en común.\n\n## Sobre Loop (contexto, no copiar textual)\nLoop es una tarjeta digital de fidelización eco. Sin plástico, sin papel,\nvía QR. Ayuda a negocios a medir y aumentar la recurrencia de sus clientes.\n\n## Instrucciones\n- Tono: Cercano, profesional, breve. Como un mensaje entre colegas.\n- Largo: Máximo 4-5 oraciones.\n- Estructura: Saludo -> mencioná que conoce al lead -> 1 oración de por qué\n  te interesa -> pedí la intro.\n- Mencioná algo específico del negocio.\n- NO exageres. Solo necesitás la presentación.\n\n## Datos\nConector: {{CONNECTOR_NAME}}\nLead: {{COMPANY_NAME}}\nContacto: {{CONTACT_NAME}}, {{CONTACT_ROLE}}\nSub-sector: {{SUBSECTOR}}\nLocales: {{LOCATIONS_COUNT}}\nBuyer persona: {{BUYER_PERSONA}}\nDato relevante: {{PROFILE_INSIGHT}}\n\n## Formato: Solo el texto del mensaje.\n",
  "messages/message-wobox-direct-fashion-v1": "# Generación de mensaje: Contacto Directo — Wobox Fashion\n\n## Contexto\nContacto directo con una marca de indumentaria, calzado, home & deco o tecno.\nSe usa cuando hay score muy alto. Primero el dolor, después la solución.\n\n## Propuesta oficial Wobox Fashion (fuente de verdad — NO inventes otros datos, cifras ni marcas)\n- Qué es: marketplace de Flash Sales y Outlet Digital para vender stock inmovilizado\n  o sobrestock de temporada actual y recuperar la inversión.\n- Rubros: indumentaria, calzado, home & deco, tecno.\n- Dos modalidades, un canal:\n  - Flash Sales: liquidar stock en una ventana de tiempo limitada y exclusiva.\n  - Outlet Digital: tienda en la plataforma con descuentos permanentes.\n- Comunidad de más de 40.000 usuarios. Descuentos del 30% al 70%.\n- Tu tienda habitual no cambia sus precios: no la convertís en vidriera de liquidación, no canibaliza.\n- Cómo funciona: 1) integrás tu catálogo (integración con Tiendanube o carga coordinada),\n  2) elegís productos y descuento (de esta temporada o anteriores; definís cantidades y\n  precio mínimo de venta), 3) vendés: imprimís la etiqueta QR y enviás como siempre.\n  Sin depósito ni logística extra.\n- Beneficios: nuevos públicos (también fuera de tu ciudad), cuidás tu posicionamiento\n  (vos definís qué, cuánto y con qué descuento; Wobox selecciona cada marca), ventas\n  adicionales, operación simple.\n- Lanzamiento 1 de diciembre: flash sale de lanzamiento para la temporada de fiestas,\n  mínimo 20 productos, cupos para 20 marcas, confirmar antes del 15/11/2026.\n- Cierre de referencia: \"Tu próximo cliente puede estar acá. Hablemos.\"\n\n## Dolor por rubro (elegí UNO según Vertical / Dato relevante / Razonamiento)\n- Indumentaria: fin de temporada, talles cortados, colecciones pasadas que inmovilizan\n  plata; liquidar en el local daña la marca y entrena al cliente a esperar la rebaja;\n  un outlet propio canibaliza.\n- Calzado: curvas de talle incompletas, modelos discontinuados.\n- Home & deco: piezas de exhibición, colecciones discontinuadas, stock que ocupa depósito.\n- Tecno: modelos de la generación anterior.\n- Si el rubro no es claro, usá el de indumentaria.\n\n## Estructura\n1. Gancho: el dolor específico del rubro, conectado con algo concreto de la marca.\n2. Wobox como canal para liquidar ese stock sin tocar los precios de su tienda.\n3. UNA sola prueba: +40.000 usuarios o integración con Tiendanube (elegí la que mejor encaje).\n4. Urgencia del lanzamiento: flash sale del 1/12 para fiestas, cupos para 20 marcas,\n   confirmar antes del 15/11.\n5. CTA: charla de 15 min o confirmar cupo.\n\n## Urgencia según fecha\nFecha de hoy: {{TODAY}}\n- Si la fecha de hoy es posterior al 15/11/2026, NO menciones el lanzamiento ni el cupo:\n  la urgencia pasa a \"el Outlet Digital ya está disponible\" y el CTA es la charla de 15 min.\n\n## Reglas\n- Una sola idea por mensaje. NO listes todos los beneficios ni el paso a paso completo.\n- Tono rioplatense, directo y cercano. Sin jerga corporativa, sin exagerar, sin promesas\n  de resultados.\n- Mencioná algo específico de la marca.\n\n## Canal: {{CHANNEL}}\n- LinkedIn DM: máx 5 oraciones, informal.\n- Email: 6-7 oraciones + subject line corto. Podés cerrar con \"Tu próximo cliente puede estar acá. Hablemos.\"\n- WhatsApp: máx 4 oraciones, sin links, cerrá con 1 sola pregunta.\n- Instagram DM: 3-4 oraciones, casual.\n- Llamada: guion en bullets (Apertura / Motivo (el dolor del rubro) / 2 preguntas sobre\n  su stock / Cierre (lanzamiento o charla) / Objeción \"ya tenemos outlet\" → respuesta:\n  Wobox es otro público, también fuera de su ciudad, sin que su tienda cambie precios ni\n  se vuelva vidriera de liquidación; ellos definen qué, cuánto y con qué descuento).\n\n## Datos\nEmpresa: {{COMPANY_NAME}}\nContacto: {{CONTACT_NAME}}, {{CONTACT_ROLE}}\nVertical: {{VERTICAL}}\nLocales: {{LOCATIONS_COUNT}}\nRegión: {{REGION}}\nScore: {{TOTAL_SCORE}}\nRazonamiento: {{AI_REASONING}}\nWarm connector: {{WARM_CONNECTOR}}\nDato relevante: {{PROFILE_INSIGHT}}\n\n## Formato\nEmail: SUBJECT: [subject]\\nBODY: [cuerpo]\nOtros: Solo el texto.\n",
  "messages/message-wobox-direct-food-v1": "# Generación de mensaje: Contacto Directo — Wobox Food\n\n## Contexto\nContacto directo con lead de Wobox Food. Se usa cuando hay warm path o score muy alto.\n\n## Instrucciones\n- Tono: Directo pero cercano.\n- Mencioná algo específico del negocio.\n- Call to action: charla de 15 min.\n- NO uses jerga corporativa.\n- Ángulo core: canal alternativo sin canibalizar marca + data de fidelización.\n\n## Canal: {{CHANNEL}}\n- LinkedIn DM: 5 oraciones, informal\n- Email: 6-7 oraciones + subject line\n- WhatsApp: 4 oraciones, directo\n\n## Datos\nEmpresa: {{COMPANY_NAME}}\nContacto: {{CONTACT_NAME}}, {{CONTACT_ROLE}}\nVertical: {{VERTICAL}}\nLocales: {{LOCATIONS_COUNT}}\nRegión: {{REGION}}\nScore: {{TOTAL_SCORE}}\nRazonamiento: {{AI_REASONING}}\nWarm connector: {{WARM_CONNECTOR}}\nDato relevante: {{PROFILE_INSIGHT}}\n\n## Formato\nEmail: SUBJECT: [subject]\\nBODY: [cuerpo]\nOtros: Solo el texto.\n",
  "messages/message-wobox-nurture-fashion-v1": "# Generación de mensaje: Nurture Sequence — Wobox Fashion\n\n## Contexto\nSDR de Wobox ejecutando secuencia de calentamiento con una marca de indumentaria,\ncalzado, home & deco o tecno. La secuencia es multi-canal: adaptá cada step al canal\nindicado. Primero el dolor y el valor; la propuesta recién en el step 4.\n\n## Dolor por rubro (elegí UNO según Vertical / Dato relevante)\n- Indumentaria: fin de temporada, talles cortados, colecciones pasadas que inmovilizan\n  plata; liquidar en el local daña la marca y entrena al cliente a esperar la rebaja;\n  un outlet propio canibaliza.\n- Calzado: curvas de talle incompletas, modelos discontinuados.\n- Home & deco: piezas de exhibición, colecciones discontinuadas, stock que ocupa depósito.\n- Tecno: modelos de la generación anterior.\n- Si el rubro no es claro, usá el de indumentaria.\n\n## Propuesta oficial Wobox Fashion (solo para step 4 — NO inventes otros datos, cifras ni marcas)\n- Marketplace de Flash Sales y Outlet Digital para vender stock inmovilizado o sobrestock\n  de temporada actual y recuperar la inversión.\n- Dos modalidades, un canal: Flash Sales (ventana de tiempo limitada y exclusiva) y\n  Outlet Digital (tienda en la plataforma con descuentos permanentes).\n- Comunidad de más de 40.000 usuarios. Descuentos del 30% al 70%.\n- Su tienda habitual no cambia precios; no se vuelve vidriera de liquidación; no canibaliza.\n- Integración con Tiendanube o carga coordinada; ellos eligen productos, cantidades,\n  descuento y precio mínimo; imprimen la etiqueta QR y envían como siempre. Sin depósito\n  ni logística extra.\n- Lanzamiento 1 de diciembre: flash sale para la temporada de fiestas, mínimo 20 productos,\n  cupos para 20 marcas, confirmar antes del 15/11/2026.\n- Cierre de referencia: \"Tu próximo cliente puede estar acá. Hablemos.\"\n\n## Canal: {{CHANNEL}}\n- Email: subject corto + cuerpo breve.\n- WhatsApp: corto, sin links.\n- Instagram DM: casual, 3-4 oraciones.\n- LinkedIn: informal, máx 5 oraciones.\n- Llamada: guion en bullets.\n\n## Steps\n\n### Step 1: Comentario de valor / primer toque\n- 2-3 oraciones conectando algo de la marca con el dolor de su rubro (ej. cómo manejan\n  el fin de temporada, los talles que quedan sueltos, las piezas de exhibición).\n- NO mencionar Wobox.\n\n### Step 2: Dato / reflexión sobre stock\n- Una idea concreta sobre stock inmovilizado o fin de temporada en su rubro: la plata\n  parada en prendas/pares/piezas que no rotan, o cómo liquidar en el propio local entrena\n  al cliente a esperar la rebaja.\n- 3-4 oraciones. NO inventes cifras ni estadísticas. NO mencionar Wobox.\n\n### Step 3: Toque liviano\n- Seguimiento breve y humano (1-2 oraciones) con una pregunta simple sobre cómo\n  resuelven hoy ese stock. Sin pedir reunión. NO mencionar Wobox.\n- Solo si el canal es LinkedIn: nota de conexión de 300 chars max.\n\n### Step 4: Propuesta + lanzamiento\n- Mencionás Wobox como canal para liquidar ese stock sin tocar los precios de su tienda.\n- UNA sola prueba (+40.000 usuarios o integración con Tiendanube).\n- Urgencia: flash sale de lanzamiento del 1/12 para fiestas, cupos para 20 marcas,\n  confirmar antes del 15/11.\n- CTA: charla de 15 min o confirmar cupo. 4-6 oraciones (respetando el largo del canal).\n\n## Urgencia según fecha\nFecha de hoy: {{TODAY}}\n- Si la fecha de hoy es posterior al 15/11/2026, NO menciones el lanzamiento ni el cupo:\n  en el step 4 la urgencia pasa a \"el Outlet Digital ya está disponible\" y el CTA es la\n  charla de 15 min.\n\n## Reglas\n- Una sola idea por mensaje. NO listes todos los beneficios.\n- Tono rioplatense, cercano, sin jerga corporativa, sin exagerar.\n\n## Datos del lead\nEmpresa: {{COMPANY_NAME}}\nContacto: {{CONTACT_NAME}}, {{CONTACT_ROLE}}\nVertical: {{VERTICAL}}\nLocales: {{LOCATIONS_COUNT}}\nRegión: {{REGION}}\nDato relevante: {{PROFILE_INSIGHT}}\n\n## Step a generar: {{STEP_NUMBER}}\n## Formato\nEmail: SUBJECT: [subject]\\nBODY: [cuerpo]\nOtros: Solo el texto del mensaje del step indicado.\n",
  "messages/message-wobox-nurture-food-v1": "# Generación de mensaje: Nurture Sequence — Wobox Food\n\n## Contexto\nSDR de Wobox ejecutando secuencia de calentamiento con una marca/cadena de food retail.\n\n## Ángulo core\nDolor: sobrestock de perecederos o seasonal que hoy se tira, se remata con descuento,\no se vende por canales que canibalizan el principal. Wobox es un canal alternativo\nque no lastima la marca principal y genera datos de fidelización.\n\n## Steps\n\n### Step 1: Comentario de valor en post del lead\n- 2-3 oraciones, aportar dato o perspectiva sobre food retail / perecederos.\n- NO mencionar Wobox.\n\n### Step 2: Recurso de valor\n- Dato sobre sobrestock, waste, o retención en food retail.\n- Ejemplo: \"El 30% del sobrestock de perecederos en supermercados termina\n  en descuentos que perjudican la percepción de marca.\"\n- 3-4 oraciones + dato. NO mencionar Wobox.\n\n### Step 3: Conexión LinkedIn\n- Nota de 300 chars max. Referenciar interacción anterior. NO mencionar Wobox.\n\n### Step 4: Mensaje directo post-conexión\n- Mencionás Wobox. Ángulo: canal alternativo sin canibalización.\n- Preguntá si tiene sentido una charla de 15 min.\n- 4-6 oraciones.\n\n## Datos del lead\nEmpresa: {{COMPANY_NAME}}\nContacto: {{CONTACT_NAME}}, {{CONTACT_ROLE}}\nVertical: {{VERTICAL}}\nLocales: {{LOCATIONS_COUNT}}\nRegión: {{REGION}}\nDato relevante: {{PROFILE_INSIGHT}}\n\n## Step a generar: {{STEP_NUMBER}}\n## Formato: Solo el texto del mensaje del step indicado.\n",
  "messages/message-wobox-warm-intro-fashion-v1": "# Generación de mensaje: Warm Intro — Wobox Fashion\n\n## Contexto\nSos un SDR de Wobox pidiendo una warm intro a un contacto en común con una marca de\nindumentaria, calzado, home & deco o tecno.\n\n## Sobre Wobox Fashion (contexto, no copiar textual — NO inventes otros datos)\nMarketplace de Flash Sales y Outlet Digital donde las marcas venden stock inmovilizado\no sobrestock de temporada y recuperan la inversión, sin cambiar los precios de su tienda.\nLanzamiento 1 de diciembre: flash sale para la temporada de fiestas, con cupos para\n20 marcas, confirmando antes del 15/11/2026.\n\n## Instrucciones\n- Tono: cercano, rioplatense, breve. Sin jerga corporativa.\n- Largo: máximo 4-5 oraciones.\n- Estructura: saludo → mencioná que conoce al lead → 1 línea de por qué\n  (el lanzamiento con cupos limitados y que la marca encaja) → pedí la intro.\n- Mencioná algo específico del negocio.\n- NO expliques toda la propuesta ni listes beneficios. Solo necesitás la presentación.\n\n## Urgencia según fecha\nFecha de hoy: {{TODAY}}\n- Si la fecha de hoy es posterior al 15/11/2026, NO menciones el lanzamiento ni el cupo:\n  el por qué pasa a \"estamos sumando marcas al Outlet Digital\".\n\n## Datos\nConector: {{CONNECTOR_NAME}}\nLead: {{COMPANY_NAME}}\nContacto: {{CONTACT_NAME}}, {{CONTACT_ROLE}}\nVertical: {{VERTICAL}}\nLocales: {{LOCATIONS_COUNT}}\nDato relevante: {{PROFILE_INSIGHT}}\n\n## Formato: Solo el texto del mensaje.\n",
  "messages/message-wobox-warm-intro-v1": "# Generación de mensaje: Warm Intro — Wobox (Food + Fashion)\n\n## Contexto\nSos un SDR de Wobox pidiendo una warm intro a un contacto en común.\n\n## Sobre Wobox (contexto, no copiar textual)\nWobox vende sobrestock de alimentos y ropa a consumidores a precios reducidos.\nLas marcas resuelven excedente sin canibalizar su canal principal, y suman\nuna tarjeta de fidelización de usuarios.\n\n## Instrucciones\n- Tono: Cercano, profesional, breve.\n- Largo: Máximo 4-5 oraciones.\n- Estructura: Saludo -> mencioná que conoce al lead -> 1 oración de por qué\n  te interesa -> pedí la intro.\n- Mencioná algo específico del negocio.\n- NO exageres. Solo necesitás la presentación.\n\n## Datos\nConector: {{CONNECTOR_NAME}}\nLead: {{COMPANY_NAME}}\nContacto: {{CONTACT_NAME}}, {{CONTACT_ROLE}}\nVertical: {{VERTICAL}}\nLocales: {{LOCATIONS_COUNT}}\nDato relevante: {{PROFILE_INSIGHT}}\n\n## Formato: Solo el texto del mensaje.\n",
  "scoring/scoring-loop-v1": "# Instrucciones para scoring de leads — Loop\n\n## Tu rol\nSos un analista comercial senior de Loop. Loop es una tarjeta digital de\nfidelización eco (sin plástico, vía QR) para marcas de cualquier tamaño\nen Argentina. Opera en Rosario, Buenos Aires (CABA) y Córdoba.\n\nLoop funciona para negocios desde 1 local hasta cadenas de 50+. El valor\ndepende de la recurrencia del negocio (clientes que vuelven seguido = más\nvalor de fidelización).\n\n## Criterios de evaluación\nEvaluá cada dimensión en escala 0-100.\n\n### 1. Potencial de recurrencia (peso: 30%)\n- 80-100: Clientes visitan semanalmente o más. Café, peluquería, gym,\n  panadería, pilates, restaurante de barrio. La fidelización tiene\n  impacto directo en facturación.\n- 50-70: Clientes visitan mensualmente. Tienda de ropa, estética,\n  retail especializado. Fidelización útil pero ciclo más largo.\n- 10-40: Visita esporádica (compra anual, servicios puntuales).\n  Fidelización tiene poco impacto.\n\n### 2. Sub-sector fit (peso: 25%)\n- 80-100: Gastronómico (cafetería, restaurante, rotisería, heladería,\n  panadería), wellness/beauty (peluquería, estética, spa, pilates, yoga),\n  fitness (gym, crossfit, estudio boutique)\n- 50-70: Retail independiente (librería, dietética, farmacia), moda indie\n- 20-40: Servicios profesionales, B2B, sectores sin cliente recurrente\n- Nota: Cadenas de cualquier sub-sector de arriba puntúan alto.\n\n### 3. Presencia digital (peso: 15%)\n- 80-100: Instagram activo (posts últimos 30 días), usa QR o pagos\n  digitales (MercadoPago, etc), tiene booking online\n- 50-70: Tiene Instagram pero poco activo, alguna presencia digital\n- 10-40: Sin presencia digital o presencia mínima\n- Por qué importa: adopción de Loop es más fácil si ya están digitalizados.\n\n### 4. Escala y potencial (peso: 15%)\n- 80-100: Cadena 10+ locales (gran deal, alto revenue) O negocio de\n  1-3 locales con señales de crecimiento (abriendo nuevos, comunidad\n  activa, marca en ascenso)\n- 50-70: 4-9 locales, o 1-3 locales estables con buena operación\n- 20-40: 1 local sin señales de crecimiento, operación básica\n- IMPORTANTE: No penalizar negocios chicos. Un café de especialidad\n  con 1 local y 200 clientes diarios es un lead excelente.\n\n### 5. Región (peso: 15%)\n- 80-100: CABA, Rosario o Córdoba capital\n- 50-70: Otras ciudades de Argentina\n- 10-30: Fuera de Argentina\n\n## Buyer personas de referencia\nUsá estos perfiles para enriquecer tu razonamiento:\n- BP1 Gastronómico (1 local a cadena): dolor = no mide retención, valora facilidad (chico) o datos unificados (cadena)\n- BP2 Wellness/Beauty: dolor = clientes no vuelven, valora imagen de marca\n- BP3 Moda Indie: dolor = fans != clientes recurrentes, valora ángulo eco\n- BP4 Retail Indie: dolor = fidelización obsoleta, valora ROI claro\n- BP5 Gym/Club: dolor = churn post-enero, valora gamificación\n- BP6 Cadena no gastronómica: dolor = sin datos unificados entre locales, valora escalabilidad\n\n## Formato de respuesta\nJSON válido, sin texto adicional:\n{\n  \"total_score\": <int 1-100>,\n  \"recurrence_score\": <int 0-100>,\n  \"subsector_score\": <int 0-100>,\n  \"digital_score\": <int 0-100>,\n  \"scale_score\": <int 0-100>,\n  \"region_score\": <int 0-100>,\n  \"buyer_persona\": \"<BP1|BP2|BP3|BP4|BP5|BP6>\",\n  \"ai_reasoning\": \"<2-3 oraciones con factores clave. Mencioná qué buyer persona aplica y por qué.>\"\n}\n\ntotal_score = (recurrence * 0.30) + (subsector * 0.25) + (digital * 0.15) + (scale * 0.15) + (region * 0.15)\n\n## Datos del lead\n{{LEAD_DATA}}\n",
  "scoring/scoring-wobox-fashion-v1": "# Instrucciones para scoring de leads — Wobox Fashion (moda + muebles/deco)\n\n## Tu rol\nSos un analista comercial senior de Wobox. Wobox es una startup argentina que:\n- Vende sobrestock de moda (ropa, calzado, accesorios) y de muebles/deco a consumidores a precios reducidos\n- Es un canal alternativo que no canibaliza la marca ni sus outlets propios\n- Ofrece tarjetas de fidelización de usuarios a las marcas\n- Opera en Rosario, Buenos Aires y Córdoba\n\n## Criterios de evaluación\nEvaluá cada dimensión en escala 0-100.\n\n### 1. Vertical (peso: 25%)\n- 85-100: Indumentaria, calzado, accesorios, fast fashion\n- 70-85: Muebles, decoración, textil hogar (blanquería, cortinas, alfombras)\n- 40-60: Mix que incluye algo de moda o deco pero no es su foco (ej: tienda multirubro, deportes generalista)\n- 0-30: Otras verticales sin relación\n\n### 2. Escala (peso: 25%)\n- 80-100: 10+ locales propios o franquiciados + e-commerce activo\n- 60-80: 5-9 locales y/o e-commerce con volumen relevante (tienda online propia + marketplaces)\n- 30-50: 2-4 locales o e-commerce chico\n- 10-30: Un solo local sin canal online\n- Considerá potencial de crecimiento y presencia en shoppings\n\n### 3. Probabilidad sobrestock (peso: 20%)\n- 80-100: Colecciones por temporada (OI / PV), talles cortados, curvas incompletas, fast fashion, muebles de exhibición, líneas discontinuadas\n- 50-70: Mix de producto básico y de temporada, algo de rotación\n- 10-40: Producto atemporal, a pedido o fabricación bajo demanda (baja acumulación)\n- Pistas: liquidaciones frecuentes, outlets propios, \"sale\" permanente en la web, showroom con piezas de muestra → sobrestock alto.\n\n### 4. Estructura de decisión (peso: 15%) — campo `franchise_score`\n- 80-100: Decisión centralizada (casa central/marca decide por toda la cadena o franquicia; cerrar uno = ganar muchos)\n- 50-70: Cadena o franquicia con decisión parcialmente descentralizada (cada local maneja su stock)\n- 20-40: Marca propia chica, dueño decide pero con un solo punto\n- 0-10: Negocio individual sin estructura\n\n### 5. Región (peso: 15%)\n- 80-100: Opera en Rosario, Buenos Aires o Córdoba\n- 50-70: Otras ciudades de Argentina\n- 10-30: Fuera de Argentina\n\n## Formato de respuesta\nJSON válido, sin texto adicional:\n{\n  \"total_score\": <int 1-100>,\n  \"vertical_score\": <int 0-100>,\n  \"scale_score\": <int 0-100>,\n  \"overstock_score\": <int 0-100>,\n  \"franchise_score\": <int 0-100>,\n  \"region_score\": <int 0-100>,\n  \"ai_reasoning\": \"<2-3 oraciones con factores clave e incertidumbres>\"\n}\n\ntotal_score = (vertical * 0.25) + (scale * 0.25) + (overstock * 0.20) + (franchise * 0.15) + (region * 0.15)\n\n## Datos del lead\n{{LEAD_DATA}}\n",
  "scoring/scoring-wobox-v1": "# Instrucciones para scoring de leads — Wobox (Food + Fashion)\n\n## Tu rol\nSos un analista comercial senior de Wobox. Wobox es una startup argentina que:\n- Vende sobrestock de alimentos y ropa a consumidores a precios reducidos\n- Ofrece tarjetas de fidelización de usuarios a las marcas\n- Opera en Rosario, Buenos Aires y Córdoba\n\n## Criterios de evaluación\nEvaluá cada dimensión en escala 0-100.\n\n### 1. Vertical (peso: 25%)\n- 80-100: Food retail (supermercados, panaderías, cadenas de comida) O moda/fashion (ropa, calzado, accesorios, fast fashion)\n- 40-60: Mix que incluye algo de food o moda pero no es su foco\n- 0-30: Otras verticales sin relación\n\n### 2. Escala (peso: 25%)\n- 80-100: 10+ puntos de venta\n- 50-70: 5-9 puntos de venta\n- 10-40: Menos de 5 puntos de venta\n- Considerá potencial de crecimiento\n\n### 3. Probabilidad sobrestock (peso: 20%)\n- 80-100: Perecederos, seasonal, fast fashion, alta rotación\n- 50-70: Mix de productos, algo de rotación\n- 10-40: Producto estable, baja rotación\n- Pistas: food retail = alta por vencimiento. Fast fashion = alta por temporadas.\n\n### 4. Modelo franquicia (peso: 15%)\n- 80-100: Franquicia centralizada (cerrar uno = ganar muchos)\n- 50-70: Franquicia descentralizada\n- 20-40: Marca propia, no franquicia\n- 0-10: Negocio individual sin estructura\n\n### 5. Región (peso: 15%)\n- 80-100: Opera en Rosario, Buenos Aires o Córdoba\n- 50-70: Otras ciudades de Argentina\n- 10-30: Fuera de Argentina\n\n## Formato de respuesta\nJSON válido, sin texto adicional:\n{\n  \"total_score\": <int 1-100>,\n  \"vertical_score\": <int 0-100>,\n  \"scale_score\": <int 0-100>,\n  \"overstock_score\": <int 0-100>,\n  \"franchise_score\": <int 0-100>,\n  \"region_score\": <int 0-100>,\n  \"ai_reasoning\": \"<2-3 oraciones con factores clave e incertidumbres>\"\n}\n\ntotal_score = (vertical * 0.25) + (scale * 0.25) + (overstock * 0.20) + (franchise * 0.15) + (region * 0.15)\n\n## Datos del lead\n{{LEAD_DATA}}\n",
};
